"""Outei Tsukinomiya (ares-outei-tsukinomiya): sus modelos 3D de Inazuma Eleven Ares como referencia (busto de frente,
perfil y espalda), calcados sobre la rejilla de unidades de cabeza. El equipo de la Luna: casi todos con el pelo blanco,
gris o en degradado. Lucas Star (Ichihoshi Hikaru) solo tiene el modelo con la camiseta de Japón (Orion), que es el mismo
aspecto."""

from chars import CHARS, L, OUTC, ell, outline, pal, strand
from heads import quad

WHITE = (248, 248, 248, 255)


def fringe(pts, c='mid'):
    return L(outline(pts), c, 'f')


def braid(pts, c='deep', r=4.0):
    """Trenza: una cadena de óvalos que se tocan."""
    return [L(ell(x, y, r, r * 1.2), c, 'f', ln=True) for x, y in pts]


